mapper.insert:

    SELECT
        'MASG'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(MESSAGE_NO), LENGTH('MASG' ) + 1)), 0) + 1, 6, '0')
    FROM CHAT_MESSAGE

INSERT INTO CHAT_MESSAGE (
	MESSAGE_NO
	, MESSAGE
	, CREATE_DATE
	, CHATROOM_NO
	, PRJ_NO
	, USER_ID
) VALUES (
	#{messageNo}
	, #{message}
	, SYSDATE
	, #{chatroomNo}
	, #{prjNo}
	, #{userId}
)
